let body = $json.body;
if (typeof body === "string") { try { body = JSON.parse(body); } catch (e) { body = null; } }
if (!body || typeof body !== "object" || Array.isArray(body)) body = $json;
const TYPES = ["fiche", "page", "faq"];
// Texte brut : retire balises HTML, entités courantes et caractères nuls (refusés par PostgreSQL)
const nettoyer = (s) => String(s == null ? "" : s)
  .replace(/\u0000/g, "")
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/gi, " ").replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, "<").replace(/&gt;/gi, ">").replace(/&amp;/gi, "&")
  .replace(/[ \t\u00a0]+/g, " ").replace(/\s*\n\s*/g, "\n").trim();
const action = String(body.action || "").trim().toLowerCase();
const source_type = String(body.source_type || "").trim().toLowerCase();
const source_id = String(body.source_id == null ? "" : body.source_id).trim().slice(0, 100);
const titre = nettoyer(body.titre).slice(0, 200);
const url = String(body.url || "").trim().slice(0, 500);
const contenu = nettoyer(body.contenu).slice(0, 20000);
let erreur = "";
if (!["upsert", "delete"].includes(action)) erreur = "action invalide (upsert ou delete attendu)";
else if (!TYPES.includes(source_type)) erreur = "source_type invalide (fiche, page ou faq attendu)";
else if (!source_id) erreur = "source_id requis";
else if (url && !/^https:\/\/(www\.)?madeleine-riviera\.fr\//.test(url)) erreur = "url hors du domaine madeleine-riviera.fr";
// Un upsert sans contenu revient à retirer l'élément de l'index
const vide = !erreur && action === "upsert" && !contenu;
return { json: {
  valide: !erreur, erreur: erreur,
  action: vide ? "delete" : action, vide: vide,
  source_type: source_type, source_id: source_id,
  titre: titre, url: url, contenu: contenu
} };

const TAILLE = 800, CHEVAUCHEMENT = 100;
const texte = String($json.contenu || "");
const chunks = [];
let debut = 0;
while (debut < texte.length) {
  let fin = Math.min(debut + TAILLE, texte.length);
  if (fin < texte.length) {
    // coupure naturelle (fin de phrase ou de ligne) dans les 40 % finaux, sinon à l'espace le plus proche
    const seuil = Math.floor(TAILLE * 0.6);
    const zone = texte.slice(debut + seuil, fin);
    const idx = Math.max(zone.lastIndexOf(". "), zone.lastIndexOf("! "), zone.lastIndexOf("? "), zone.lastIndexOf("\n"));
    if (idx >= 0) fin = debut + seuil + idx + 1;
    else {
      const sp = texte.lastIndexOf(" ", fin);
      if (sp > debut + Math.floor(TAILLE * 0.5)) fin = sp;
    }
  }
  const morceau = texte.slice(debut, fin).trim();
  if (morceau) chunks.push(morceau);
  if (fin >= texte.length) break;
  let prochain = fin - CHEVAUCHEMENT;
  const sp = texte.indexOf(" ", prochain);
  if (sp !== -1 && sp < fin) prochain = sp + 1;   // repartir au début d'un mot
  debut = Math.max(prochain, debut + 1);
}
// Le titre est ajouté au texte envoyé au modèle (meilleure pertinence), mais pas au contenu stocké
const textes = chunks.map(c => $json.titre ? $json.titre + "\n\n" + c : c);
return { json: {
  source_type: $json.source_type, source_id: $json.source_id,
  titre: $json.titre, url: $json.url,
  chunks: chunks, textes_embedding: textes, nb: chunks.length
} };

const ctx = $('Découper en extraits').item.json;
const r = $json || {};
const lire = (arr) => arr.map(x => Array.isArray(x) ? x : (x && x.embedding));
let vecs = null;
if (Array.isArray(r.data)) {
  // format OpenAI (/ai/v1/embeddings) : [{ embedding, index }] ; format natif : [[...], [...]]
  const d = r.data.slice();
  if (d.length && !Array.isArray(d[0]) && d[0] && d[0].index != null) d.sort((a, b) => a.index - b.index);
  vecs = lire(d);
} else if (r.result && Array.isArray(r.result.data)) {
  vecs = lire(r.result.data);
}
if (!Array.isArray(vecs) || vecs.length !== ctx.chunks.length) {
  throw new Error("Embeddings reçus : " + (vecs ? vecs.length : 0) + ", attendus : " + ctx.chunks.length + " — réponse : " + JSON.stringify(r).slice(0, 200));
}
for (const v of vecs) {
  if (!Array.isArray(v) || v.length !== 1024 || !v.every(x => typeof x === "number" && isFinite(x))) {
    throw new Error("Embedding invalide : 1024 nombres attendus (colonne vector(1024))");
  }
}
const lignes = ctx.chunks.map((c, i) => ({
  titre: ctx.titre || null, url: ctx.url || null, contenu: c, embedding: "[" + vecs[i].join(",") + "]"
}));
const lignes_json = JSON.stringify(lignes);
const esc = (s) => String(s).replace(/'/g, "''");
const sql = "WITH suppression AS (DELETE FROM ia_index WHERE source_type = '" + esc(ctx.source_type) + "' AND source_id = '" + esc(ctx.source_id) + "') INSERT INTO ia_index (source_type, source_id, titre, url, contenu, embedding) SELECT '" + esc(ctx.source_type) + "'::text, '" + esc(ctx.source_id) + "'::text, r.titre, r.url, r.contenu, r.embedding::vector FROM jsonb_to_recordset('" + esc(lignes_json) + "'::jsonb) AS r(titre text, url text, contenu text, embedding text)";
return { json: { source_type: ctx.source_type, source_id: ctx.source_id, nb: lignes.length, lignes_json: lignes_json, sql: sql } };

const n = $('Normaliser le contenu').item.json;
if (!n.valide) return { json: { code: 400, corps: { erreur: n.erreur } } };
if (n.action === "delete") {
  return { json: { code: 200, corps: { supprime: true, source_type: n.source_type, source_id: n.source_id, vide: n.vide } } };
}
const d = $('Assembler les lignes').item.json;
return { json: { code: 200, corps: { indexe: true, nb_extraits: d.nb } } };

// ⚠️ Le source_id doit être IDENTIQUE à celui envoyé par la Flow Directus (webhook), sinon l'index contiendra des doublons.
// Si la Flow envoie par exemple "F12" pour la fiche 12, renseigner PREFIXE.fiche = "F".
const PREFIXE = { fiche: "", page: "", faq: "" };
const BASE = "https://madeleine-riviera.fr";
const lire = (nom) => $(nom).all().flatMap(i => Array.isArray(i.json.data) ? i.json.data : []);
const out = [];
for (const f of lire("Lister les fiches")) {
  out.push({ json: { action: "upsert", source_type: "fiche", source_id: PREFIXE.fiche + String(f.id),
    titre: f.nom_commercial || "", url: f.slug ? BASE + "/fiche/" + f.slug : "",
    contenu: [f.nom_commercial, f.presentation].filter(Boolean).join("\n\n") } });
}
for (const p of lire("Lister les pages")) {
  out.push({ json: { action: "upsert", source_type: "page", source_id: PREFIXE.page + String(p.id),
    titre: p.titre || "", url: p.slug ? BASE + "/" + p.slug : "",
    contenu: [p.titre, p.contenu].filter(Boolean).join("\n\n") } });
}
for (const q of lire("Lister la FAQ")) {
  out.push({ json: { action: "upsert", source_type: "faq", source_id: PREFIXE.faq + String(q.id),
    titre: q.question || "", url: BASE + "/faq",
    contenu: [q.question, q.reponse].filter(Boolean).join("\n\n") } });
}
if (out.length === 0) throw new Error("Aucun contenu publié récupéré : API Directus indisponible ou filtres incorrects");
return out;
